<script setup lang="ts">
import {computed,ref} from 'vue'
import {Search,Users,ArrowUpRight,Download,FileText,CheckCircle2,Send,ArrowRight,Clock3,X} from 'lucide-vue-next'
import {data,latin,money,num,months,organization,sum,saveCSV} from './data'
import MetricValue from './MetricValue.vue'
const props=defineProps<{familyId:string;role:string;services?:boolean}>()
const emit=defineEmits<{family:[string];receipt:[{title:string;lines:string[]}];services:[]}>()
const query=ref(''),person=ref(''),quarter=ref(0),agency=ref(''),kind=ref(''),direction=ref(''),selectedPayment=ref('')
const family=computed(()=>data.families.find(x=>x.id===props.familyId)??data.families[0]!)
const families=computed(()=>data.families.filter(f=>latin(f.id+' '+f.address+' '+f.members.map(m=>m.name).join(' ')).toLowerCase().includes(latin(query.value).toLowerCase())))
const selectedMonths=computed(()=>Array.from({length:12},(_,i)=>i).filter(i=>!quarter.value||Math.floor(i/3)===quarter.value-1))
const rows=computed(()=>family.value.members.filter(m=>!person.value||person.value===m.id).flatMap(m=>m.rows.map(r=>({...r,member:m}))).filter(r=>(!agency.value||r.o===agency.value)&&(!kind.value||r.t===kind.value)&&(!direction.value||r.d===direction.value)))
const allRows=computed(()=>family.value.members.flatMap(m=>m.rows))
const values=computed(()=>months.map((_,i)=>sum(rows.value.map(r=>r.arr[i]??0))))
const total=computed(()=>sum(selectedMonths.value.map(i=>values.value[i]??0)))
const maximum=computed(()=>Math.max(1,...values.value))
const agencies=computed(()=>[...new Set(allRows.value.map(r=>r.o))])
const directions=computed(()=>[...new Set(allRows.value.map(r=>r.d))])
const directionLabels:Record<string,string>={ben:'Ijtimoiy nafaqalar',pen:'Pensiya to‘lovlari',low:'Kam ta’minlangan oilalar',comp:'Kompensatsiya',once:'Bir martalik to‘lov',ins:'Ijtimoiy sug‘urta',fund:'Jamg‘arma ko‘magi',svc:'Xizmatlar'}
const suggestions=computed(()=>{const map=new Map<string,{id:string;got:boolean;why:string[]}>();family.value.members.forEach(m=>m.suggestions.forEach(s=>{const old=map.get(s.id);map.set(s.id,{...s,got:s.got||!!old?.got,why:[...new Set([...(old?.why??[]),...s.why])]})}));return [...map.values()]})
const applying=ref(''),applicant=ref(''),reason=ref(''),accepted=ref(false),error=ref(''),message=ref('')
type Application={id:string;service:string;familyId:string;memberId:string;reason:string;created:string;status:string}
const applications=ref<Application[]>([])
try{const value=JSON.parse(localStorage.getItem('nasp-social-demo-applications-v2')??'[]');if(Array.isArray(value))applications.value=value}catch{ /* Optional demo history. */ }
const familyApplications=computed(()=>applications.value.filter(a=>a.familyId===family.value.id))
function chooseFamily(id:string){emit('family',id);person.value=agency.value=kind.value=direction.value='';quarter.value=0;selectedPayment.value=''}
function receipt(){emit('receipt',{title:'Oila bo‘yicha ko‘rsatilgan ko‘mak',lines:[`2025-yil ${quarter.value?quarter.value+'-chorak':'yakuni'}`,`Oila: ${family.value.id} · ${latin(data.regions[family.value.region])}`,`Jami: ${num(total.value)} so‘m`,...rows.value.map(r=>`${latin(r.member.name)} · ${latin(r.n)} · ${num(sum(selectedMonths.value.map(i=>r.arr[i]??0)))} so‘m`),'Prototip ma’lumotnomasi. Rasmiy hujjat emas.']})}
function exportRows(){saveCSV('Fuqaro_oila_tolovlari.csv',[['Shaxs','Chora','Idora',...selectedMonths.value.map(i=>months[i]!)],...rows.value.map(r=>[latin(r.member.name),latin(r.n),organization(r.o),...selectedMonths.value.map(i=>r.arr[i]??0)])])}
function apply(id:string){applying.value=id;applicant.value=person.value||family.value.members[0]!.id;reason.value='';accepted.value=false;error.value=''}
function submit(){if(!applicant.value||!accepted.value||!reason.value.trim()){error.value='Oila a’zosini, murojaat mazmunini va tasdiqni kiriting.';return}const application:Application={id:'DEMO-'+Date.now().toString(36).toUpperCase(),service:applying.value,familyId:family.value.id,memberId:applicant.value,reason:reason.value,created:new Date().toLocaleDateString('uz-UZ'),status:'Qabul qilindi'};try{const next=[application,...applications.value];localStorage.setItem('nasp-social-demo-applications-v2',JSON.stringify(next));applications.value=next;applying.value='';message.value=application.id+' — namunaviy ariza qabul qilindi. Mas’ul idoraga jo‘natilmadi.'}catch{error.value='Brauzer xotirasiga saqlab bo‘lmadi.'}}
</script>
<template><div class="family-view"><div class="section-heading"><div><h2>{{ services?'Huquqlar va xizmatlar':role==='citizen'?'Mening oilam':'Fuqaro va oila pasporti' }}</h2><p>Har bir idoradan ko‘rsatilgan ko‘mak bir tarixda · 2025</p></div><div class="heading-actions"><button class="np-button" @click="receipt"><FileText :size="14"/>Ma’lumotnoma</button><button class="np-button" @click="exportRows"><Download :size="14"/>Eksport</button></div></div><div v-if="role!=='citizen'" class="np-card family-lookup"><label class="np-search"><Search :size="15"/><input v-model="query" placeholder="Shaxs, oila yoki hududni qidirish" aria-label="Oila qidiruvi"/></label><select :value="family.id" aria-label="Oila tanlash" @change="chooseFamily(($event.target as HTMLSelectElement).value)"><option v-for="item in families" :key="item.id" :value="item.id">{{ item.id }} · {{ latin(item.members[0]?.name) }} · {{ item.members.length }} a’zo</option></select><span>{{ families.length }} oila</span></div><div class="family-heading"><div class="family-avatar"><Users :size="25"/></div><div><h3>{{ latin(family.members[0]?.name) }}</h3><p>{{ latin(data.regions[family.region]) }} · {{ latin(family.address) }}</p><span v-for="tag in family.tags" :key="tag" class="np-tag blue">{{ latin(tag) }}</span></div><span class="np-tag" :class="family.members.some(m=>m.source)?'green':'amber'">{{ family.members.some(m=>m.source)?'Manba to‘lovlari · F.I.Sh. shartli':'Namunaviy oila' }}</span></div><template v-if="!services"><div class="family-overview"><div class="family-total"><small>Tanlangan davrda ko‘rsatilgan ko‘mak</small><strong><MetricValue :value="total"/><span>so‘m</span></strong><div><span>{{ new Set(rows.map(r=>r.n)).size }} chora</span><span>{{ family.members.length }} oila a’zosi</span><span>{{ new Set(rows.map(r=>r.o)).size }} idora</span></div></div><div class="np-card family-members"><button :class="{selected:!person}" @click="person=''">Butun oila <b>{{ family.members.length }}</b></button><button v-for="member in family.members" :key="member.id" :class="{selected:person===member.id}" @click="person=member.id"><span>{{ latin(member.name) }}<small>{{ latin(member.relation)||'Oila a’zosi' }} · {{ member.age??'—' }} yosh</small></span><b>{{ money(sum(member.rows.flatMap(r=>selectedMonths.map(i=>r.arr[i]??0)))) }}</b></button></div></div><div class="np-card"><div class="np-toolbar"><h3>To‘lovlar tarixi</h3><div class="np-segment"><button v-for="q in [0,1,2,3,4]" :key="q" :class="{active:quarter===q}" @click="quarter=q">{{ q?q+'-chorak':'Yil' }}</button></div><select v-model="agency" aria-label="Oila to‘lov idorasi"><option value="">Barcha idoralar</option><option v-for="key in agencies" :key="key" :value="key">{{ organization(key) }}</option></select><select v-model="kind" aria-label="Oila chora turi"><option value="">Barcha turlar</option><option value="kaf">Ijtimoiy kafolat</option><option value="mol">Moliyaviy ko‘mak</option><option value="imt">Imtiyoz</option></select><select v-model="direction" aria-label="Oila yo‘nalishi"><option value="">Barcha yo‘nalishlar</option><option v-for="d in directions" :key="d" :value="d">{{ directionLabels[d]??d }}</option></select></div><div class="np-month-chart family-chart"><button v-for="(value,i) in values" :key="i" :class="{dim:!selectedMonths.includes(i)}" :title="months[i]+': '+num(value)+' so‘m'" @click="quarter=Math.floor(i/3)+1"><b>{{ money(value) }}</b><i :style="{height:Math.max(3,value/maximum*100)+'%',animationDelay:i*40+'ms'}"/><span>{{ months[i] }}</span></button></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Chora / oluvchi</th><th>Idora</th><th v-for="i in selectedMonths" :key="i">{{ months[i] }}</th><th>Jami</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.member.id+row.id"><td><button class="text-button" @click="selectedPayment=selectedPayment===row.member.id+row.id?'':row.member.id+row.id">{{ latin(row.n) }}</button><small>{{ latin(row.member.name) }}</small></td><td>{{ organization(row.o) }}</td><td v-for="i in selectedMonths" :key="i">{{ row.arr[i]?money(row.arr[i]!):'—' }}</td><td><b>{{ money(sum(selectedMonths.map(i=>row.arr[i]??0))) }}</b></td><td><button class="icon-button" aria-label="To‘lov kvitansiyasi" @click="emit('receipt',{title:latin(row.n),lines:[latin(row.member.name),organization(row.o),'2025-yil',...selectedMonths.map(i=>months[i]+': '+num(row.arr[i]??0)+' so‘m'),'Namunaviy kvitansiya.']})"><FileText :size="15"/></button></td></tr><tr v-if="!rows.length"><td :colspan="selectedMonths.length+4" class="np-empty">Bu kesimda to‘lov yozuvi mavjud emas.</td></tr></tbody></table></div><div v-if="selectedPayment" class="np-note">Tanlangan to‘lovning barcha oylari yuqoridagi qatorda ko‘rsatilgan. Kvitansiya belgisi bilan alohida hujjatni oching.</div></div><div v-if="family.signals.length" class="family-signals"><div v-for="[level,text] in family.signals" :key="text" class="np-notice" :class="level==='warn'?'amber':'blue'">{{ latin(text) }}</div></div><div class="family-next"><div><h3>Hali foydalanilmagan imkoniyatlar</h3><p>Oila tarkibi va olingan ko‘mak asosidagi namunaviy tavsiyalar.</p></div><button class="np-button primary" @click="emit('services')">Huquqlar va xizmatlar <ArrowRight :size="14"/></button></div></template><template v-else><div class="np-notice blue">Tavsiyalar namunaviy. Xizmatga huquq mas’ul idoraning tekshiruvi bilan tasdiqlanadi.</div><div class="service-grid"><article v-for="item in suggestions" :key="item.id" class="np-card service-card"><span class="service-icon"><CheckCircle2 v-if="item.got" :size="22"/><ArrowUpRight v-else :size="22"/></span><span class="np-tag" :class="item.got?'green':'blue'">{{ item.got?'Foydalanilmoqda':'Tavsiya etiladi' }}</span><h3>{{ latin(data.services[item.id]?.[0]) }}</h3><small>{{ latin(data.services[item.id]?.[1]) }}</small><p>{{ latin(data.services[item.id]?.[2]) }}</p><ul><li v-for="why in item.why" :key="why">{{ latin(why) }}</li></ul><button v-if="!item.got" class="np-button primary" @click="apply(item.id)"><Send :size="14"/>Namunaviy ariza berish</button></article></div><div class="np-card"><h3>Murojaatlarim <span class="np-tag blue">{{ familyApplications.length }}</span></h3><p v-if="!familyApplications.length" class="np-empty">Bu oila bo‘yicha hali namunaviy ariza yo‘q.</p><div v-for="item in familyApplications" :key="item.id" class="application-row"><Clock3 :size="18"/><div><strong>{{ latin(data.services[item.service]?.[0]) }}</strong><small>{{ item.id }} · {{ item.created }}</small><p>{{ item.reason }}</p></div><span class="np-tag green">{{ item.status }}</span></div></div><details class="np-card"><summary>Barcha xizmatlar katalogi · {{ Object.keys(data.services).length }}</summary><div v-for="(service,id) in data.services" :key="id" class="service-line"><div><b>{{ latin(service[0]) }}</b><p>{{ latin(service[2]) }}</p><small>{{ latin(service[1]) }}</small></div><button class="np-button" @click="apply(String(id))">Ariza</button></div></details></template><p v-if="message" class="np-notice green" role="status">{{ message }}</p><div v-if="applying" class="np-overlay" @click.self="applying=''" @keydown.esc="applying=''"><form class="np-dialog" role="dialog" aria-modal="true" aria-labelledby="service-application-title" @submit.prevent="submit"><header><div><span class="np-tag amber">Namunaviy ariza</span><h2 id="service-application-title">{{ latin(data.services[applying]?.[0]) }}</h2></div><button type="button" class="icon-button" aria-label="Arizani yopish" @click="applying=''"><X :size="20"/></button></header><label>Oila a’zosi<select v-model="applicant"><option v-for="m in family.members" :key="m.id" :value="m.id">{{ latin(m.name) }}</option></select></label><label>Murojaat mazmuni<textarea v-model="reason" rows="4" placeholder="Xizmat bo‘yicha murojaatni kiriting"/></label><label class="np-check"><input v-model="accepted" type="checkbox"/>Namoyish arizasi ekanini tasdiqlayman</label><p v-if="error" class="np-notice red">{{ error }}</p><button class="np-button primary" type="submit"><Send :size="15"/>Arizani saqlash</button><small>Ariza shu brauzerda saqlanadi. Tashqi idoraga yuborilmaydi.</small></form></div></div></template>
<style scoped>.family-lookup{display:flex;align-items:center;gap:15px;margin-bottom:18px}.family-lookup .np-search{flex:1}.family-lookup select{max-width:50%}.family-lookup>span{font-size:11px;color:#8c9aad;white-space:nowrap}.family-heading{display:flex;gap:15px;align-items:center;margin:20px 0}.family-avatar{height:58px;width:58px;border-radius:16px;display:grid;place-items:center;background:#eaf1ff;color:#396bd6}.family-heading h3{font-weight:750;font-size:17px}.family-heading p{color:#7f8da1;font-size:12px;margin:3px 0 6px}.family-heading>.np-tag{margin-left:auto}.family-overview{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px}.family-total{border-radius:14px;background:linear-gradient(115deg,#f0f5ff,#e9f5f7);border:1px solid #dbe5f4;padding:28px;display:flex;flex-direction:column;justify-content:center;color:#204475}.family-total>small{font-size:12px;color:#7f95b3}.family-total>strong{font-size:36px;margin:15px 0;letter-spacing:-.05em}.family-total>strong>span{font-size:14px;margin-left:9px;letter-spacing:0}.family-total>div{display:flex;gap:20px;font-size:11px;color:#6d87a8}.family-members{display:grid;gap:4px;max-height:250px;overflow:auto}.family-members button{display:flex;justify-content:space-between;align-items:center;gap:12px;text-align:left;font-size:12px;padding:10px;border-radius:7px}.family-members button.selected{background:#edf3ff;color:#345dd0}.family-members small{display:block;font-size:10px;color:#96a3b4}.family-members b{font-size:11px}.family-chart{height:190px;margin:22px 0 30px}.family-chart button b{font-size:9px}.family-chart .dim{opacity:.25}.family-signals{display:grid;gap:10px;margin-top:20px}.family-next{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:20px;padding:22px;background:var(--card);border:1px solid var(--border);border-radius:12px}.family-next h3{font-size:14px;font-weight:700}.family-next p{font-size:11px;color:#8d9aab;margin-top:4px}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:20px 0}.service-card{display:flex;align-items:flex-start;flex-direction:column;gap:12px}.service-icon{height:42px;width:42px;border-radius:12px;background:#edf4fe;color:#3a70d9;display:grid;place-items:center}.service-card h3{line-height:1.5}.service-card small,.service-card li{font-size:11px;color:#95a2b3}.service-card p{font-size:12px;color:#718198;line-height:1.7}.service-card .np-button{margin-top:auto}.service-line,.application-row{display:flex;gap:14px;padding:16px 0;border-bottom:1px solid var(--border);align-items:center}.service-line p,.application-row p{font-size:11px;color:#8b99ac}.service-line small,.application-row small{font-size:10px;color:#96a2b3;display:block}.service-line b,.application-row strong{font-size:12px}.service-line .np-button,.application-row>.np-tag{margin-left:auto}.np-dialog label{display:grid;gap:8px;font-size:12px;margin:18px 0}.np-dialog .np-check{display:flex}.np-dialog>small{display:block;font-size:11px;color:#8695a8;margin-top:14px}.family-view>details{margin-top:20px}@media(max-width:850px){.family-overview{grid-template-columns:1fr}.service-grid{grid-template-columns:1fr 1fr}.family-lookup{flex-wrap:wrap}.family-heading{flex-wrap:wrap}}@media(max-width:550px){.service-grid{grid-template-columns:1fr}}</style>
